// The mic probe. One job: answer, on real hardware, whether the G2's
// microphone hears *the other person* well enough to coach on.
//
// The format question is largely answered already: the EvenHub simulator's
// README (0.9.5) documents what it emits as **16000 Hz, signed 16-bit
// little-endian, mono, 100 ms per event (3200 bytes, 1600 samples)** — 32000
// bytes/sec, the wideband case Deepgram wants, not the 8 kHz narrowband one
// D-125 feared. The probe still measures it, because the simulator's spec is
// a statement about the simulator; only hardware can confirm the firmware
// agrees.
//
// Everything else in the Even plan waits on this (WEARABLE_AR §3a.1). It is
// deliberately ugly and self-contained: no auth, no network, no engine.
//
// Three sources so it is useful before the glasses arrive:
//   glasses — `audioControl(true, Glasses)`, PCM over the Even bridge
//   phone   — the same bridge, the phone's own mic
//   browser — getUserMedia, so the whole path is testable on a laptop today
//
// The decisive test is the playback: record a two-person conversation, press
// Play, and listen. If the far side is intelligible the standalone glasses
// app is on; if it is a beamformed wash of only your own voice, it is off and
// the phone keeps the mic (D-228 stands).

import {
  AudioInputSource,
  AudioSpeakerRole,
  CreateStartUpPageContainer,
  TextContainerProperty,
  waitForEvenAppBridge,
  type EvenAppBridge,
} from '@evenrealities/even_hub_sdk'
import { DISPLAY } from '../config'

type Source = 'glasses' | 'phone' | 'browser'

const root = document.getElementById('probe')!
root.innerHTML = `
  <h1>G2 mic probe</h1>
  <p class="lede">Record a real two-person conversation, then play it back. The question is whether you can hear <em>the other person</em>.</p>

  <div class="row" id="sources"></div>

  <div class="row">
    <button class="btn primary" id="rec">Record</button>
    <button class="btn" id="play" disabled>Play back</button>
    <button class="btn" id="save" disabled>Save .wav</button>
    <button class="btn" id="clear" disabled>Clear</button>
  </div>

  <p class="status" id="status">Idle.</p>

  <dl class="metrics" id="metrics"></dl>
  <p class="hint">The simulator documents 16000 Hz, 16-bit mono, 3200 bytes per 100 ms event, so 32000 bytes per second. Anything near 16000 bytes per second would mean 8 kHz narrowband, the bad case for transcription. The number to watch, though, is not here: it is whether you can hear the other person on playback.</p>
  <pre class="log" id="log"></pre>
`

const $ = <T extends HTMLElement>(s: string) => root.querySelector<T>(s)!
const statusEl = $('#status')
const metricsEl = $('#metrics')
const logEl = $<HTMLPreElement>('#log')
const recBtn = $<HTMLButtonElement>('#rec')
const playBtn = $<HTMLButtonElement>('#play')
const saveBtn = $<HTMLButtonElement>('#save')
const clearBtn = $<HTMLButtonElement>('#clear')

function log(line: string): void {
  const t = new Date().toISOString().slice(11, 23)
  logEl.textContent = `${t}  ${line}\n${logEl.textContent}`.slice(0, 8000)
}

// MARK: - What we measure

const stats = {
  frames: 0,
  bytes: 0,
  startedAt: 0,
  roles: { self: 0, other: 0, unknown: 0 } as Record<string, number>,
  directions: [] as number[],
  frameSizes: new Set<number>(),
}
let chunks: Uint8Array[] = []
let recording = false
let source: Source = 'glasses'

/** What the simulator documents, and therefore what hardware should match. */
const EXPECTED = { rate: 16000, bytesPerSec: 32000, frameBytes: 3200 }

/** Bytes/sec → the format actually arriving, which may not be the documented one. */
function inferred(): { bytesPerSec: number; guess: string } {
  const secs = (Date.now() - stats.startedAt) / 1000
  if (secs <= 0.5 || stats.bytes === 0) return { bytesPerSec: 0, guess: '—' }
  const bps = stats.bytes / secs
  // Assume the common case, 16-bit signed mono, and name the nearest rate.
  const rate = bps / 2
  const known = [8000, 16000, 22050, 24000, 32000, 44100, 48000]
  const near = known.reduce((a, b) => (Math.abs(b - rate) < Math.abs(a - rate) ? b : a))
  const off = Math.abs(near - rate) / near
  let guess = off < 0.12 ? `~${near} Hz, 16-bit mono` : `${Math.round(rate)} Hz if 16-bit mono (no clean match)`
  if (off < 0.12 && near === EXPECTED.rate) guess += ' ✓ matches the documented format'
  else if (off < 0.12) guess += ` ✗ expected ${EXPECTED.rate} Hz`
  return { bytesPerSec: Math.round(bps), guess }
}

function render(): void {
  const { bytesPerSec, guess } = inferred()
  const secs = stats.startedAt ? (Date.now() - stats.startedAt) / 1000 : 0
  const dirs = stats.directions
  const rows: Array<[string, string]> = [
    ['Source', source],
    ['Elapsed', `${secs.toFixed(1)} s`],
    ['Frames', String(stats.frames)],
    ['Bytes', stats.bytes.toLocaleString()],
    ['Bytes / second', bytesPerSec ? bytesPerSec.toLocaleString() : '—'],
    ['Inferred format', guess],
    ['Frame sizes seen', stats.frameSizes.size ? `${[...stats.frameSizes].sort((a, b) => a - b).join(', ')} (expect ${EXPECTED.frameBytes})` : '—'],
    ['speakerRole self / other / unknown', `${stats.roles.self} / ${stats.roles.other} / ${stats.roles.unknown}`],
    ['direction min / max / last', dirs.length ? `${Math.min(...dirs)} / ${Math.max(...dirs)} / ${dirs[dirs.length - 1]}` : '— (null: phone mic or older host)'],
  ]
  metricsEl.innerHTML = rows.map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join('')
}
setInterval(() => { if (recording) render() }, 250)

function accept(pcm: Uint8Array, role: string, direction: number | null): void {
  if (!recording) return
  if (!stats.startedAt) stats.startedAt = Date.now()
  stats.frames++
  stats.bytes += pcm.byteLength
  stats.frameSizes.add(pcm.byteLength)
  stats.roles[role] = (stats.roles[role] ?? 0) + 1
  if (direction !== null && direction !== undefined) stats.directions.push(direction)
  chunks.push(pcm)
}

// MARK: - The Even bridge

let bridge: EvenAppBridge | null = null
let unsubscribe: (() => void) | null = null

async function connectBridge(): Promise<EvenAppBridge | null> {
  if (bridge) return bridge
  const hasHost = typeof window !== 'undefined'
    && typeof (window as { flutter_inappwebview?: { callHandler?: unknown } }).flutter_inappwebview?.callHandler === 'function'
  if (!hasHost) return null
  try {
    bridge = await Promise.race([
      waitForEvenAppBridge(),
      new Promise<null>((r) => setTimeout(() => r(null), 2500)),
    ])
  } catch {
    bridge = null
  }
  return bridge
}

/** The SDK requires a startup page before the glasses mic will open. */
async function ensureStartupPage(b: EvenAppBridge): Promise<void> {
  const text = new TextContainerProperty({
    containerID: 1,
    containerName: 'probe',
    xPosition: 16,
    yPosition: 100,
    width: DISPLAY.width - 32,
    height: 88,
    borderWidth: 0,
    borderColor: 0,
    borderRadius: 0,
    paddingLength: 0,
    isEventCapture: 1,
    content: 'Mic probe — recording',
  })
  const result = await b.createStartUpPageContainer(
    new CreateStartUpPageContainer({ containerTotalNum: 1, textObject: [text] }),
  )
  log(`startup page result ${result}`)
}

async function startBridgeAudio(src: Exclude<Source, 'browser'>): Promise<boolean> {
  const b = await connectBridge()
  if (!b) {
    log('No Even bridge. Open this inside the Even app, or pick Browser mic.')
    return false
  }
  if (src === 'glasses') await ensureStartupPage(b)
  unsubscribe = b.onEvenHubEvent((event) => {
    const audio = event.audioEvent
    if (!audio) return
    const pcm = audio.audioPcm instanceof Uint8Array ? audio.audioPcm : new Uint8Array(audio.audioPcm ?? [])
    const role = audio.speakerRole ?? AudioSpeakerRole.Unknown
    accept(pcm, String(role), audio.direction ?? null)
  })
  const ok = await b.audioControl(true, src === 'glasses' ? AudioInputSource.Glasses : AudioInputSource.Phone)
  log(`audioControl(true, ${src}) -> ${ok}`)
  return ok !== false
}

async function stopBridgeAudio(): Promise<void> {
  unsubscribe?.()
  unsubscribe = null
  if (bridge) {
    const ok = await bridge.audioControl(false)
    log(`audioControl(false) -> ${ok}`)
  }
}

// MARK: - Browser mic, so this is testable before the glasses arrive

let mediaStream: MediaStream | null = null
let audioCtx: AudioContext | null = null
let processor: ScriptProcessorNode | null = null

async function startBrowserAudio(): Promise<boolean> {
  try {
    mediaStream = await navigator.mediaDevices.getUserMedia({ audio: { channelCount: 1, echoCancellation: false, noiseSuppression: false, autoGainControl: false } })
  } catch (err) {
    log(`getUserMedia refused: ${(err as Error).message}`)
    return false
  }
  audioCtx = new AudioContext()
  const src = audioCtx.createMediaStreamSource(mediaStream)
  // Deprecated, and exactly right for a probe: no worklet module to ship.
  processor = audioCtx.createScriptProcessor(4096, 1, 1)
  processor.onaudioprocess = (ev) => {
    const input = ev.inputBuffer.getChannelData(0)
    const out = new Int16Array(input.length)
    for (let i = 0; i < input.length; i++) {
      const s = Math.max(-1, Math.min(1, input[i]!))
      out[i] = s < 0 ? s * 0x8000 : s * 0x7fff
    }
    accept(new Uint8Array(out.buffer.slice(0)), 'unknown', null)
  }
  src.connect(processor)
  processor.connect(audioCtx.destination)
  log(`browser mic open at ${audioCtx.sampleRate} Hz`)
  return true
}

async function stopBrowserAudio(): Promise<void> {
  processor?.disconnect()
  processor = null
  mediaStream?.getTracks().forEach((t) => t.stop())
  mediaStream = null
  await audioCtx?.close()
  audioCtx = null
}

// MARK: - Playback and export, both assuming 16-bit signed mono

/** One contiguous buffer at offset 0, so `.buffer` is safe to hand to Blob. */
function joined(): Uint8Array {
  const total = chunks.reduce((n, c) => n + c.byteLength, 0)
  const out = new Uint8Array(new ArrayBuffer(total))
  let at = 0
  for (const c of chunks) { out.set(c, at); at += c.byteLength }
  return out
}

function sampleRate(): number {
  const { bytesPerSec } = inferred()
  if (!bytesPerSec) return 16000
  const rate = bytesPerSec / 2
  const known = [8000, 16000, 22050, 24000, 32000, 44100, 48000]
  return known.reduce((a, b) => (Math.abs(b - rate) < Math.abs(a - rate) ? b : a))
}

function wav(pcm: Uint8Array, rate: number): Blob {
  const header = new ArrayBuffer(44)
  const v = new DataView(header)
  const ascii = (off: number, s: string) => { for (let i = 0; i < s.length; i++) v.setUint8(off + i, s.charCodeAt(i)) }
  ascii(0, 'RIFF'); v.setUint32(4, 36 + pcm.byteLength, true); ascii(8, 'WAVE')
  ascii(12, 'fmt '); v.setUint32(16, 16, true); v.setUint16(20, 1, true); v.setUint16(22, 1, true)
  v.setUint32(24, rate, true); v.setUint32(28, rate * 2, true); v.setUint16(32, 2, true); v.setUint16(34, 16, true)
  ascii(36, 'data'); v.setUint32(40, pcm.byteLength, true)
  return new Blob([header, pcm.buffer as ArrayBuffer], { type: 'audio/wav' })
}

/** Playback is the real test, and unlike a download it works inside a WebView. */
async function playBack(): Promise<void> {
  const pcm = joined()
  if (!pcm.byteLength) return
  const rate = sampleRate()
  const ctx = new AudioContext()
  await ctx.resume()
  const samples = new Int16Array(pcm.buffer as ArrayBuffer, pcm.byteOffset, Math.floor(pcm.byteLength / 2))
  const buf = ctx.createBuffer(1, samples.length, rate)
  const ch = buf.getChannelData(0)
  for (let i = 0; i < samples.length; i++) ch[i] = samples[i]! / 0x8000
  const node = ctx.createBufferSource()
  node.buffer = buf
  node.connect(ctx.destination)
  node.onended = () => { statusEl.textContent = 'Playback finished.'; void ctx.close() }
  node.start()
  statusEl.textContent = `Playing ${(samples.length / rate).toFixed(1)} s back at ${rate} Hz.`
  log(`playback ${samples.length} samples at ${rate} Hz`)
}

// MARK: - Wiring

const sourcesEl = $('#sources')
sourcesEl.innerHTML = (['glasses', 'phone', 'browser'] as Source[])
  .map((s) => `<button class="btn src" data-src="${s}" aria-pressed="${s === source}">${s}</button>`)
  .join('')
sourcesEl.addEventListener('click', (ev) => {
  const b = (ev.target as HTMLElement).closest<HTMLButtonElement>('.src')
  if (!b || recording) return
  source = b.dataset.src as Source
  for (const el of sourcesEl.querySelectorAll<HTMLButtonElement>('.src')) {
    el.setAttribute('aria-pressed', String(el.dataset.src === source))
  }
  render()
})

recBtn.addEventListener('click', async () => {
  if (recording) {
    recording = false
    recBtn.textContent = 'Record'
    recBtn.classList.add('primary')
    if (source === 'browser') await stopBrowserAudio()
    else await stopBridgeAudio()
    statusEl.textContent = `Stopped. ${(stats.bytes / Math.max(1, sampleRate() * 2)).toFixed(1)} s captured. Press Play back and listen for the other person.`
    playBtn.disabled = saveBtn.disabled = clearBtn.disabled = stats.bytes === 0
    render()
    return
  }
  statusEl.textContent = 'Opening the microphone…'
  const ok = source === 'browser' ? await startBrowserAudio() : await startBridgeAudio(source)
  if (!ok) { statusEl.textContent = 'Could not open that microphone. See the log.'; return }
  recording = true
  stats.startedAt = 0
  recBtn.textContent = 'Stop'
  recBtn.classList.remove('primary')
  statusEl.textContent = 'Recording. Have a real conversation — let the other person talk.'
})

playBtn.addEventListener('click', () => void playBack())

saveBtn.addEventListener('click', () => {
  const url = URL.createObjectURL(wav(joined(), sampleRate()))
  const a = document.createElement('a')
  a.href = url
  a.download = `g2-mic-${source}-${sampleRate()}hz.wav`
  a.click()
  setTimeout(() => URL.revokeObjectURL(url), 10_000)
  log('save attempted (a download may be blocked inside the Even WebView — playback is the reliable test)')
})

clearBtn.addEventListener('click', () => {
  chunks = []
  stats.frames = stats.bytes = stats.startedAt = 0
  stats.roles = { self: 0, other: 0, unknown: 0 }
  stats.directions = []
  stats.frameSizes.clear()
  playBtn.disabled = saveBtn.disabled = clearBtn.disabled = true
  statusEl.textContent = 'Cleared.'
  render()
})

render()
log('probe ready')
